<?php
require_once 'config.php';
$cat=trim($_GET['cat']??'');$stmt=$conn->prepare("SELECT id,name FROM categories WHERE name=? LIMIT 1");$stmt->bind_param('s',$cat);$stmt->execute();$category=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$category){header('Location: home.php');exit;}
$stmt=$conn->prepare("SELECT p.* FROM products p WHERE p.category_id=? AND p.is_active=1 ORDER BY p.created_at DESC");$stmt->bind_param('i',$category['id']);$stmt->execute();$res=$stmt->get_result();$products=[];while($r=$res->fetch_assoc())$products[]=$r;$stmt->close();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($cat)?> - Style Hub</title><link rel="stylesheet" href="style.css"></head><body><header><a class="logo" href="home.php">Style Hub</a><nav><a href="home.php">Home</a><a class="active" href="category.php?cat=Men">Men</a><a href="category.php?cat=Women">Women</a><a href="category.php?cat=Kids">Kids</a><a href="category.php?cat=Accessories">Accessories</a></nav><div class="header-right"><form class="search-box" action="search.php"><input name="q" placeholder="Search clothes..."></form><?php if(isset($_SESSION['user_id'])):?><a class="auth-btn" href="cart.php">Cart</a><a class="auth-btn" href="logout.php">Logout</a><?php endif;?></div></header><main class="section"><h2><?=htmlspecialchars($cat)?> Collection</h2><div class="product-grid"><?php foreach($products as $p):?><article class="product-card"><img src="<?=htmlspecialchars($p['image'])?>" alt=""><div class="product-info"><h3><?=htmlspecialchars($p['name'])?></h3><p class="price">₹<?=number_format($p['price'],2)?></p><button class="primary-btn add-cart" data-product="<?=$p['id']?>">Add to Cart</button></div></article><?php endforeach;?></div></main><script src="script.js"></script></body></html>
